INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62252077', 62252077, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI YOGYAKARTA 03', 'Layanan Pos Bantuan Hukum Pengadilan Negeri Yogyakarta', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 100000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1000 JL / 1317 orang', 'Layanan Pos Bantuan Hukum di lingkungan Peradilan Umum - Pengadilan Negeri Yogyakarta', 'Formasi Penerimaan 1. Penyedia Jasa pada Pos Bantuan Hukum berasal dari Lembaga Sipil penyedia Advokasi Hukum dan/atau unit kerja Advokasi Hukum pada organisasi profesi advokat dan/atau lembaga konsultansi dan bantuan hukum di Perguruan Tinggi. 2. Telah memiliki surat pengesahan pendirian badan hukum dari Kementrian Hukum dan HAM 3. Telah terakreditasi sebagaimana SK Menteri Hukum dan HAM ; 4. Memiliki Kantor/Cabang/Perwakilan di Wilayah Hukum Pengadilan Negeri Yogyakarta. 5. Bersedia memberikan jasa layanan bantuan hukum pada Pos Bantuan Hukum Pengadilan Negeri Yogyakarta selama tahun anggaran 2026 dan sesuai jam kerja pada Pengadilan Negeri Yogyakarta 6. Petugas pada Pos Bantuan Hukum adalah Advokat, S1 Hukum atau Sarjana Hukum Islam, yang menguasai Hukum dan Memiliki staf atau anggota yang memiliki gelar Sarjana Hukum atau Sarjana Hukum Islam. 7. Petugas pada Pos Bantuan Hukum ditunjuk oleh Pimpinan Lembaga Bantuan Hukum yang bersangkutan dan tidak boleh berganti sampai akhir masa kontrak. 8. Penyedia telah terdaftar dalam Aplikasi SIKAP ( Sistem Informasi Kinerja Penyedia ) C. Persyaratan 1. Mengajukan surat penawaran yang ditujukan kepada Ketua Pengadilan Negeri Yogyakarta UP. Pejabat Pengadaan Posbakum TA 2026 Pengadilan Negeri Yogyakarta yang dilengkapi dengan Rencana Anggaran Biaya (RAB). 2. Penyedia telah terdaftar dalam APLIKASI SIKAP (Sistem Informasi Kinerja Penyedia). 3. Berbentuk Badan Hukum dengan melampirkan Akta Notaris dan terdaftar di Kementerian Hukum dan HAM atau izin pendirian dari Rektor bagi Perguruan Tinggi. 4. Telah terakreditasi oleh kemenkumham RI 5. Memiliki kemampuan menyediakan fasilitas/peralatan/perlengkapan untuk melaksanakan pekerjaan Jasa Konsultansi ini, yaitu: Komputer, Printer dan Alat Tulis Kantor; 6. Surat keterangan Domisili Lembaga 7. Melampirkan Fotocopy KTP Pimpinan dan yang akan ditunjuk sebagai petugas Posbakum 8. Menyediakan minimal 2 orang petugas bantuan hukum di setiap ruang sidang 9. Melampirkan NPWP dan Nomor Rekening atas nama Lembaga 10. Melampirkan Bukti Setor Pajak Tahunan (SPT) 5 Tahun terakhir 11. Membuat surat pernyataan bersedia menandatangani Pakta Integritas 12. Tidak masuk dalam daftar hitam 13. Bersedia mengikuti Tes Kompetensi 14. Bersedia menandatangani pernyataan tidak mengajukan keberatan atas hasil seleksi. 15. Bersedia tunduk pada aturan dan ketentuan Pengadaan Jasa Posbakum di Pengadilan Negeri Yogyakarta.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 371350);
