INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62292765', 62292765, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Plakat Untuk Kegiatan Operasional dan Pemeliharaan Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Republik Indonesia Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '40.0 OK', 'ekerjaan ini mencakup pengadaan plakat sebagai bagian dari kebutuhan pendukung kegiatan jamuan tamu pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan untuk 20 (dua puluh) orang dalam 2 (dua) kegiatan selama 1 (satu) Tahun Anggaran. Plakat digunakan sebagai cendera mata atau bentuk apresiasi dalam kegiatan kedinasan, pertemuan resmi, dan penerimaan tamu. Pelaksanaan pekerjaan meliputi penyediaan plakat sesuai kebutuhan setiap kegiatan yang dilaksanakan selama Tahun Anggaran berjalan, dengan memperhatikan ketentuan administrasi, kesesuaian penggunaan, serta efisiensi anggaran.', 'Plakat yang disediakan merupakan plakat yang layak, rapi, dan sesuai untuk kegiatan. Jumlah plakat yang disediakan sebanyak 40 unit yang diperuntukkan bagi 20 orang pada masing-masing dari 2 kegiatan. Plakat dilengkapi dengan identitas atau keterangan kegiatan sesuai kebutuhan. Spesifikasi teknis plakat disesuaikan dengan standar umum cendera mata dan digunakan khusus untuk mendukung pelaksanaan kegiatan jamuan tamu. Seluruh pengadaan dilaksanakan sesuai dengan ketentuan administrasi dan kebutuhan kegiatan yang berlaku.', 10000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 371976);
