INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62252465', 62252465, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Alih Daya Pendukung Kesekretariatan Peta Jalan Ekonomi Digital', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 134855710, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Mengumpulkan data yang lengkap dan mutakhir, terkait perkembangan perdagangan dalam negeri dan luar negeri. Melakukan pengolahan data menggunakan perangkat lunak statistik, spreadsheet, atau aplikasi manajemen data lainnya. Menyusun database sektor perdagangan yang terstruktur, rapi, dan mudah diakses untuk kepentingan analisis dan perencanaan. Membantu analisis data untuk menunjang penyusunan strategi peningkatan ekspor daerah. Membantu memantau, mengevaluasi, dan mengendalikan pelaksanaan program dan kegiatan dalam rangka implementasi strategi peningkatan ekspor daerah. Membantu menyusun materi (infografis atau bahan presentasi) dan laporan kegiatan secara terstruktur, komprehensif, dan menarik.', 'Terkumpulnya data sektor perdagangan yang lengkap, mutakhir, tervalidasi, dan siap digunakan sebagai dasar analisis dan perencanaan. Data terstruktur sektor perdagangan, termasuk database perkembangan perdagangan dalam negeri dan luar negeri, serta indikator terkait yang tersusun rapi, terdokumentasi, dan mudah diakses. Dokumen analisis data deskriptif tematik untuk mendukung penyusunan konsep dan rencana kerja strategi peningkatan ekspor daerah. Dokumen pemantauan, evaluasi, dan pengendalian pelaksanaan program dalam rangka implementasi strategi peningkatan ekspor daerah, termasuk temuan lapangan dan rekomendasi berbasis data. Materi infografis dan bahan presentasi yang informatif dan komprehensif untuk penyusunan arah kebijakan kedepan. Rekapitulasi dan ringkasan data berkala yang dapat digunakan untuk keperluan rapat koordinasi, penyusunan kebijakan, maupun evaluasi kinerja program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 372164);
