INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62255511', 62255511, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TATA USAHA NEGARA SERANG 01', 'Pengadaan Kursi dan Meja CPNS', 'Barang', 'E-Purchasing', 'Banten, Serang (Kota)', 20000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 4, set, @ 5000000 )', '1. Pengadaan Kursi dan Meja CPNS ( 4, set, @ 5000000 );', 'Meja: - Fungsi: Meja kerja staf dengan desain minimalis, kokoh, dan dilengkapi penyimpanan dokumen - Material: Kaki meja dari kayu solid yang telah melalui proses oven, Top panel (daun meja) memiliki ketebalan minimal 25 mm dari papan kayu olahan padat (MDF/HPL/MFC) yang tahan terhadap kelembapan, tahan gores, dan mudah dibersihkan - Dimensi Minimal: Panjang 120 cm x Lebar 60 cm x Tinggi 75 cm. - Dilengkapi lubang manajemen kabel (grommet), Dilengkapi laci penyimpanan yang dapat dikunci (baik laci tanam maupun laci dorong), Terdapat dop/pelapis pada ujung kaki meja, agar tidak merusak lantai, Sudut-sudut meja dibuat tumpul (rounded) untuk keamanan dan kenyamanan pengguna. Kursi: - Fungsi: Kursi kerja kantor yang mendukung posisi duduk sehat untuk durasi penggunaan lama (8 jam kerja). - Sandaran: Model sandaran tinggi/menengah berbahan jaring (mesh) untuk sirkulasi udara yang baik. - Memiliki penopang punggung bawah (lumbar support). - Ketinggian kursi dapat diatur secara mekanis (sistem hidrolik). - Memiliki sandaran tangan (armrest). - Dudukan: Busa cetak (moulded foam) dengan kepadatan tinggi yang tidak mudah kempes, dilapisi kain atau bahan sintetis berkualitas. - Kaki & Roda: Kaki bintang lima (5-star base) dengan roda (castor) yang dapat berputar 360 derajat dan bergerak lancar di permukaan lantai kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 373744);
