INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62255564', 62255564, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA WATANSOPPENG 04', 'Jasa Konsultansi Pos Bantuan Hukum (POSBAKUM)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sulawesi Selatan, Soppeng (Kab.)', 55000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '55 JL', 'Belanja Jasa Konsultan Pos Bantuan Hukum (POSBAKUM) sebanyak 55 Jam Layanan', '1. Lembaga Bantuan Hukum (LBH) dari organisasi Profesi Advokat / LBH Perguruan Tinggi / Organisasi LBH dari Lembaga Swadaya Masyarakat; 2. Memiliki struktur kepengurusan yang jelas; 3. Memiliki kantor dan alamat yang jelas di Wilayah Hukum Pengadilan Agama Watansoppeng dan atau sekitarnya 4. Telah lulus verifikasi dan akreditas sebagai pemberi bantuan hukum yang di tetapkan oleh Kementrian Hukum dan HAM RI; 5. Memiliki minimal 1 (satu) orang Advokat dibuktikan dengan Kartu Tanda Anggota Perhimpunan / Ikatan Profesi yang ditugaskan sebagai Team Leader; 6. Memiliki minimal 1 (satu) orang staf atau anggota yang nantinya bertugas di POSBAKUM Pengadilan, yang bergelar minimal Sarjana Hukum atau Sarjana Syari’ah atau mahasiswa yang telah menempuh 140 SKS yang dibuktikan dengan Kartu Hasil Studi (KHS); 7. Memiliki NPWP Lembaga / organisasi; 8. Memiliki rekening atas nama Lembaga / Organisasi / Pengurus LBH dibuktikan dengan lampiran surat keterangan dari Bank atau foto copy rekening koran; 9. Berpengalaman sebagai penyedia Jasa Layanan Posbakum di Pengadilan Agama minimal 2 (dua) tahun 10. Bersedia menyediakan alat pengolah data dan ATK untuk melaksanakan jasa Posbakum ini dibuktikan dengan surat pernyataan; 11. Surat pernyataan bersedia menandatangani Pakta Integritas. 12. Memiliki akun level penyedia pada Lembaga Pengadaan Secara Elektronik (LPSE) Mahkamah Agung RI', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 374179);
