INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62256151', 62256151, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TATA USAHA NEGARA SERANG 01', 'Pemeliharaan Kendaraan Roda 4 Pinjam Pakai dari Pemda', 'Jasa Lainnya', 'Pengadaan Langsung', 'Banten, Serang (Kota)', 82681000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 2, Unit, @ 41340600 )', '1. Pemeliharaan Kendaraan Roda 4 Pinjam Pakai dari Pemda ( 2, Unit, @ 41340600 );', '1. Spesifikasi Administrasi & Legalitas Izin Usaha: Memiliki NIB (Nomor Induk Berusaha) yang relevan (KBLI untuk Reparasi dan Perawatan Mobil). Kelas Bengkel: Minimal bengkel kategori Kelas B (mampu melakukan servis rutin, perbaikan mesin berat, hingga kelistrikan). Lokasi: Berada dalam radius maksimal (misal: 10–15 km) dari kantor instansi untuk efisiensi waktu dan biaya antar-jemput unit. 2. Spesifikasi Fasilitas & Peralatan Utama Bengkel harus memiliki peralatan yang memadai agar pengerjaan tidak dilempar ke pihak ketiga (sub-kon): Fasilitas Angkat: Memiliki Two-Post Lift atau Four-Post Lift untuk inspeksi bagian bawah kendaraan. Diagnostik: Memiliki alat Scanner Engine universal atau khusus merek tertentu (untuk mobil injeksi modern). Peralatan Standar: Memiliki Tune-up kit, kompresor udara, alat ganti oli, serta alat pengisian freon AC Area Kerja: Memiliki area servis yang bersih, terlindung dari cuaca (indoor), dan area parkir yang aman dengan pengamanan 24 jam. 3. Spesifikasi Sumber Daya Manusia (SDM) Sertifikasi: Teknisi/Mekanik memiliki sertifikasi kompetensi (minimal SMK Otomotif atau sertifikat pelatihan teknis dari ATPM). Kepala Mekanik: Tersedianya Service Advisor atau Kepala Mekanik untuk berkonsultasi mengenai estimasi kerusakan. 4. Spesifikasi Suku Cadang & Bahan Kualitas Part: Wajib menyediakan Suku Cadang Asli (Original Equipment Manufacturer/OEM) kecuali atas permintaan tertulis menggunakan part alternatif berkualitas setara. Pelumas: Menggunakan pelumas (oli) yang masih tersegel dan sesuai dengan spesifikasi viskositas kendaraan dinas. Limbah B3: Memiliki sistem pengelolaan limbah B3 (oli bekas, filter bekas) yang sesuai aturan lingkungan hidup. 5. Spesifikasi Layanan (Service Level) Garansi: Memberikan jaminan/garansi pekerjaan minimal 2 minggu atau 1.000 km setelah servis. Estimasi Biaya: Bersedia memberikan estimasi biaya (Quotation) sebelum pekerjaan dimulai. Darurat: Menyediakan layanan Emergency Roadside Assistance (layanan derek atau servis di tempat) dalam wilayah tertentu. Riwayat Servis: Bersedia memberikan/menyimpan buku riwayat servis (service record) untuk setiap kendaraan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 374586);
