INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62256203', 62256203, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TATA USAHA NEGARA SERANG 01', 'Satpam', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Serang (Kota)', 194168000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 52, OB, @ 3734000 )', '1. Satpam ( 52, OB, @ 3734000 );', 'Personil: Pendidikan: Minimal lulusan SMP/SMA atau sederajat. Kesehatan: Sehat jasmani dan rohani (bebas narkoba dibuktikan dengan surat keterangan atau tes P4GN). Kompetensi: Memiliki pengetahuan dasar tentang teknik pembersihan, penggunaan alat kebersihan, dan penggunaan bahan kimia (chemical) pembersih. Atribut: Wajib menggunakan seragam kerja yang rapi, tanda pengenal (ID Card), dan Alat Pelindung Diri (APD) seperti masker dan sarung tangan saat bekerja. Perilaku: Memiliki tata krama yang baik, jujur, dan disiplin waktu. Vendor: Izin Operasional: Wajib memiliki Surat Izin Operasional Badan Usaha Jasa Pengamanan (BUJP) yang masih berlaku dari Mabes Polri/Polda. Kepatuhan Normatif: Memberikan gaji minimal sesuai UMK/UMP terbaru, membayar lembur (jika ada), serta mengikutsertakan personil dalam BPJS Kesehatan dan BPJS Ketenagakerjaan. Pembinaan & Supervisi: Melakukan supervisi rutin oleh koordinator lapangan dan memberikan pelatihan penyegaran secara berkala kepada personil. Sistem Ganti (Back-up): Menjamin ketersediaan tenaga pengganti jika personil utama berhalangan hadir (sakit/izin) dalam waktu maksimal 2-4 jam agar pos tidak kosong.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 374684);
