INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62293758', 62293758, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Biaya Jamuan Tamu Untuk Kegiatan Operasional dan Pemeliharaan Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Republik Indonesia Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 340258000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Tahun', 'Pekerjaan ini mencakup penyediaan jamuan untuk mendukung pelaksanaan kegiatan penerimaan tamu dan pertemuan yang dilaksanakan di lingkungan Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan selama jangka waktu 1 tahun. Penyediaan jamuan dilakukan secara bertahap sesuai dengan kebutuhan dan frekuensi kegiatan yang dilaksanakan sepanjang tahun dengan memperhatikan kesesuaian kebutuhan serta ketertiban administrasi.', 'Jamuan yang disediakan berupa konsumsi kegiatan yang layak dan sesuai kebutuhan yang meliputi antara lain makanan ringan, makanan berat, minuman, serta perlengkapan penyajian jamuan. Jenis dan jumlah jamuan disesuaikan dengan jumlah peserta dan karakter kegiatan yang dilaksanakan. Penyediaan jamuan dilakukan selama 1 tahun dan disalurkan secara bertahap sesuai pelaksanaan kegiatan. Seluruh jamuan disediakan dalam kondisi bersih, higienis, dan siap disajikan, serta disesuaikan dengan ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 376152);
