INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62948485', 62948485, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PENDIDIKAN', 'Programmer 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 71685000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'a. Menulis kode program yang bersih (clean code) menggunakan bahasa pemrograman yang ditentukan (contoh: PHP, Python Django, atau Node.js). b. Mengembangkan antarmuka pengguna (UI) yang responsif berdasarkan desain Mockup/Figma yang telah disediakan. c. Merancang dan mengelola struktur database (MySQL/PostgreSQL/NoSQL) agar mampu menangani pertukaran data secara cepat. d. Melakukan pengujian mandiri melalui Unit Testing sebelum diserahkan kepada tim Quality Assurance (QA). e. Melakukan deployment aplikasi ke lingkungan staging maupun production menggunakan alat seperti Docker atau Jenkins (jika relevan). f. Memberikan dukungan teknis dan pelatihan penggunaan aplikasi kepada end-user atau administrator sistem. g. Pengembangan Perangkat Lunak: Membangun, menguji, dan mengimplementasikan fitur-fitur baru pada aplikasi sesuai dengan dokumen perancangan sistem. h. Pemeliharaan (Maintenance): Melakukan perbaikan bug (debugging) dan optimalisasi performa pada aplikasi yang sudah berjalan. i. Integrasi Sistem: Melakukan integrasi aplikasi dengan database, API pihak ketiga, atau sistem internal lainnya. j. Dokumentasi Teknis: Menyusun dokumen teknis yang meliputi Source Code Documentation, API Documentation, dan User Manual.', '• Pendidikan: Minimal S1 Teknik Informatika/Sistem Informasi/Ilmu Komputer. • Pengalaman: Minimal 2-3 tahun dalam pengembangan aplikasi (dibuktikan dengan portofolio). • Keahlian Teknis: Menguasai Framework tertentu, RESTful API, Version Control (Git), dan manajemen database. • Memiliki sertifikat komputer; • Memiliki perangkat kerja berupa Komputer/Laptop; • Mampu bekerja sendiri dan dengan tim dan bersedia bekerja overtime; • Bersedia bekerja di lokasi Dinas Pendidikan Kota Tangerang selama kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 376713);
