INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62969533', 62969533, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Paket Meeting - Pekan Panutan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 78750000, 'March 2026', 'APBD', 1, 1, '225 Orang', 'Uraian pekerjaan ini meliputi penyediaan paket layanan meeting full day untuk mendukung pelaksanaan rapat, koordinasi, sosialisasi, atau kegiatan kedinasan lainnya yang diselenggarakan selama satu hari penuh. Paket meeting full day harus mampu menunjang kelancaran kegiatan secara efektif, tertib, dan profesional. Penyedia jasa bertanggung jawab atas seluruh kebutuhan fasilitas, konsumsi, dan layanan pendukung rapat sesuai dengan ketentuan yang telah ditetapkan oleh Pejabat Pembuat Komitmen (PPK). Ruang Lingkup Pekerjaan meliputi: Penyediaan Ruang Rapat Ruang rapat yang representatif, bersih, dan nyaman. Kapasitas ruangan disesuaikan dengan jumlah peserta. Tata letak ruangan (classroom/U-shape/round table) sesuai kebutuhan. Penyediaan Konsumsi Peserta Snack pagi (coffee break pagi). Makan siang (lunch). Snack sore (coffee break sore). Minuman (air mineral, teh, kopi). Penyediaan Perlengkapan Rapat Meja dan kursi sesuai standar kenyamanan. Sound system. LCD proyektor dan layar. Flipchart/whiteboard dan alat tulis pendukung (jika diperlukan). Layanan Pendukung Petugas teknis/LO untuk membantu kelancaran kegiatan. Kebersihan ruang rapat selama kegiatan berlangsung. Pengaturan teknis sebelum dan sesudah rapat. Durasi Pelaksanaan Kegiatan dilaksanakan selama 1 (satu) hari penuh sesuai jadwal yang ditetapkan. Standar Pelayanan Pelayanan profesional, tepat waktu, dan sesuai standar pelayanan jasa perhotelan/gedung pertemuan. Konsumsi memenuhi standar kebersihan dan kelayakan konsumsi. Serah Terima Layanan Layanan dianggap selesai setelah kegiatan terlaksana dengan baik sesuai kesepakatan. Dituangkan dalam Berita Acara Penyelesaian Pekerjaan/BAST Jasa. Dengan terlaksananya paket meeting full day ini, diharapkan kegiatan rapat dapat berjalan lancar, efektif, dan mencapai tujuan yang telah ditetapka', 'Paket Pekerjaan Meeting Full Day 1. Nama Pekerjaan Paket Pekerjaan Meeting Full Day 2. Jenis Pekerjaan Pengadaan Jasa Penyelenggaraan Rapat/Meeting 3. Maksud dan Tujuan Menyediakan layanan meeting full day yang lengkap dan profesional untuk mendukung pelaksanaan rapat, koordinasi, sosialisasi, atau kegiatan kedinasan selama satu hari penuh agar berjalan efektif dan lancar. 4. Ruang Lingkup Pekerjaan Ruang lingkup pekerjaan meliputi penyediaan fasilitas, konsumsi, perlengkapan, dan layanan pendukung rapat selama kegiatan berlangsung. 5. Spesifikasi Teknis Layanan 5.1 Ruang Rapat Ruang rapat representatif, bersih, dan nyaman Kapasitas sesuai jumlah peserta Tata letak ruang: classroom/U-shape/round table (sesuai kebutuhan) Pencahayaan dan sirkulasi udara/AC memadai 5.2 Konsumsi Coffee break pagi (snack + minuman) Makan siang (menu standar, higienis, dan bergizi) Coffee break sore (snack + minuman) Air mineral tersedia selama kegiatan 5.3 Perlengkapan dan Fasilitas Rapat Meja dan kursi sesuai standar kenyamanan Sound system berfungsi baik LCD proyektor dan layar Microphone (wired/wireless) Flipchart/whiteboard dan spidol Alat tulis rapat 5.4 Layanan Pendukung Petugas teknis/LO selama kegiatan Penataan ruangan sebelum kegiatan Kebersihan ruangan selama dan setelah kegiatan Bantuan teknis operasional (audio visual) 6. Durasi Pelaksanaan 1 (satu) hari penuh sesuai jadwal yang ditetapkan oleh penyelenggara 7. Standar Pelayanan Pelayanan profesional dan tepat waktu Konsumsi memenuhi standar kebersihan dan keamanan pangan Fasilitas berfungsi baik selama kegiatan 8. Lokasi Pelaksanaan Hotel, gedung pertemuan, atau fasilitas meeting yang ditetapkan oleh penyedia dan disetujui oleh PPK 9. Personel Pelaksana Koordinator kegiatan Petugas teknis/sound system Petugas kebersihan 10. Pengendalian Mutu Pemeriksaan kesiapan fasilitas sebelum kegiatan Evaluasi kelancaran layanan selama kegiatan 11. Pembayaran Pembayaran dilaksanakan sesuai ketentuan kontrak setelah kegiatan selesai dan dituangkan dalam berita acara 12. Serah Terima Pekerjaan Dinyatakan selesai setelah kegiatan terlaksana dengan baik Dibuktikan dengan Berita Acara Penyelesaian Pekerjaan/BAST Jasa', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 379512);
